import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { parsePo, serializePo, writeCatalog } from './tools/i18n-engine/src/po.ts';
for (const locale of ['ar', 'fa', 'hi', 'th']) {
  const path = `l10n/${locale}/docs.guides.po`;
  const entries = parsePo(readFileSync(path, 'utf8'));
  const entry = entries.find(entry => !entry.obsolete && entry.references.includes('guide/cli.md'));
  assert.ok(entry, `${locale}: missing CLI guide catalog entry`);
  const rendered = readFileSync(`docs/${locale}/guide/cli.md`, 'utf8').trimEnd();
  assert.equal(entry.msgstr.replace(/\s/gu, ''), rendered.replace(/\s/gu, ''), `${locale}: non-whitespace change`);
  entry.msgstr = rendered;
  writeCatalog(path, serializePo(entries));
  console.log(`${locale}: synchronized formatted CLI guide whitespace`);
}
